<script lang="ts">import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import CreateUser from '$lib/components/database/CreateUser.svelte';import {databaseState} from '$lib/database/store';let query='';$: users=$databaseState.users.filter(u=>(u.name+' '+u.engine).toLowerCase().includes(query.toLowerCase().trim()));</script>
<Heading title="Manage Users" subtitle="Manage independent database users and connection access."><a class="btn secondary" href="/databases">Manage Databases</a></Heading><div class="stack"><section class="card table-card"><div class="table-head"><h3>Database users</h3><div class="toolbar"><label class="search"><Icon name="Search"/><input bind:value={query} placeholder="Search users…" aria-label="Search database users"/></label></div></div><div class="table-wrap"><table><thead><tr><th>Username</th><th>Engine</th><th>Databases</th><th>Access</th><th>Actions</th></tr></thead><tbody>{#each users as u}<tr><td><a class="link-btn mono native-path" href={'/databases/users/'+u.id}>{u.name}</a></td><td>{u.engine}</td><td>{Object.keys(u.grants).length}</td><td>{u.hosts.length?'Remote configured':'Private only'}</td><td><a class="btn secondary small" href={'/databases/users/'+u.id}>Manage</a></td></tr>{:else}<tr><td colspan="5">No users found.</td></tr>{/each}</tbody></table></div></section><CreateUser/></div>
